typescript.code:
import * as tt from "thinkthen";

// a parcel stuck in transit: "shipping"
const options = ["billing", "shipping", "account"];
console.log(await tt.choose("Which team owns this?",
    "My parcel is stuck in transit.", { options }));

// praise and a bug in one message: ["praise", "bug"]
const labels = ["praise", "bug", "billing", "shipping"];
console.log(await tt.tag("Which labels fit this message?",
    "Love the app, but export crashes.", { labels }));

// a batch you can cancel: abort() stops the requests
const inbox = ["Can we move Thursday's call?",
    "Checkout is down and nobody can pay."];
const stop = new AbortController();
const urgent = await tt.rank("Is this urgent?",
    inbox, { top: 1, signal: stop.signal });
// the outage is the most urgent
console.log(urgent[0].record);

rust.code:
use thinkthen::{Answer, Engine, Question};

// blocking calls, and no async runtime comes with it
let tt = Engine::from_env()?;

let asks = "Does the customer ask for a refund?";
let refund = Question::decide(asks)?.band(0.2, 0.8)?;
let texts = ["Please refund my order. It came broken.",
    "I want to send this back."];
// the compiler makes you handle "not sure"
for text in texts {
    match tt.decide(&refund, text)? {
        Answer::Yes => println!("refund: {text}"),
        Answer::No => println!("no: {text}"),
        Answer::Unsure => println!("a person: {text}"),
    }
}

c.code:
#include <stdio.h>
#include <string.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();
const char *q = "Does the customer ask for a refund?";
const char *t = "Please refund my order. It came broken.";

/* every call returns 0, or one of six error kinds */
thinkthen_answer a;
int rc = thinkthen_decide(tt, q, t, strlen(t), &a);

/* a plain ask for money back prints 1 0.99.
   1 is THINKTHEN_YES */
if (rc == THINKTHEN_OK)
    printf("%d %.2f\n", a.outcome, a.probability);
else
    puts(thinkthen_error_message(tt));

thinkthen_engine_free(tt);
